"""Lockfile read/write parity with urim-ts (shared-fixtures/lock.vectors.json, generated by urim-ts)."""

import pytest
from conftest import SHARED, load

from urim import UrimError
from urim.boundary import to_json
from urim.lock import parse_lock, serialize_lock
from urim.types import ContractRef, Lock

VECTORS = load(SHARED / "lock.vectors.json")


@pytest.mark.parametrize("v", VECTORS, ids=[v["name"] for v in VECTORS])
def test_parse_and_serialize_match_ts(v):
    r = parse_lock(v["input"])
    assert r.ok is v["ok"]
    if v["ok"]:
        assert isinstance(r.value, Lock)
        assert to_json(r.value) == v["lock"]
        assert serialize_lock(r.value) == v["text"]  # byte-identical pretty canonical text
        assert parse_lock(load_text(v["text"])).value == r.value  # round trip
    else:
        assert [i.path for i in r.issues] == v["issuePaths"]


def load_text(text):
    import json

    return json.loads(text)


def test_typed_access_is_snake_case():
    lock = parse_lock(VECTORS[0]["input"]).value
    assert lock.eval.objectives_met is True and lock.tiers[0].descriptor_hash is None


def test_writer_is_strict():
    bad = Lock(ContractRef("c", "sha256:" + "a" * 64), {"g": {"t": 2}})
    with pytest.raises(UrimError) as e:
        serialize_lock(bad)
    assert e.value.type == "lock_violation"


def test_parsed_lock_is_frozen():
    lock = parse_lock(VECTORS[0]["input"]).value
    with pytest.raises(TypeError):
        lock.cuts["gate"]["x"] = 0.1  # type: ignore[index]
